import {initFraudMonitoring} from './fraud-monitoring.mjs';
import {publicCard} from './card-model.mjs';
const root=document.querySelector('#management-root'),admin=document.body.dataset.management==='admin';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const labels={pending:'Chờ duyệt',approved:'Đã duyệt',rejected:'Từ chối'};
let members=[],section='cards';
let user=null,status='pending',cards=[],selected=null,challenge=null,loginEmail='',busy=false,resendAt=0;
async function call(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error||'Không thể kết nối máy chủ.'),{status:response.status});return result;}
const fraudMonitoring=initFraudMonitoring({root,call,back:()=>load().catch(error=>notice(error.message))});
function notice(message){let element=document.querySelector('#management-notice');if(!element){element=document.createElement('p');element.id='management-notice';element.setAttribute('role','alert');root.prepend(element);}element.textContent=message;}
async function boot(){try{user=(await call(admin?'admin/me':'auth/me')).user;if(section==='members'&&user.isOwner)await loadMembers();else await load();}catch(error){if(error.status===401)login();else if(error.status===403)denied();else notice(error.message);}}
function denied(){root.innerHTML='<section class="login-panel"><span class="eyebrow">KHU VỰC QUẢN TRỊ</span><h1>Không có quyền truy cập</h1><p>Tài khoản hiện tại không phải admin. Đăng nhập bằng email admin đã được cấu hình trên máy chủ.</p><button id="switch-account">Đăng nhập tài khoản khác</button></section>';document.querySelector('#switch-account').onclick=async()=>{try{await call('auth/logout',{});login();}catch(error){notice(error.message);}};}
function login(){root.innerHTML=`<section class="login-panel"><span class="eyebrow">${admin?'ADMIN ACCESS':'THẺ CỦA BẠN'}</span><h1>${challenge?'Xác nhận email':'Đăng nhập bằng email'}</h1><p>${challenge?`Nhập mã 6 số đã gửi đến ${e(loginEmail)}.`:'Sử dụng tài khoản email đã đăng ký trên app. Nếu chưa có tài khoản, hãy đăng ký trong ứng dụng trước.'}</p><form id="management-login">${challenge?'<label for="login-code">Mã xác nhận</label><input id="login-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required>':`<label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="email" value="${e(loginEmail)}" required>`}<p id="login-error" role="alert"></p><button>${challenge?'Xác nhận':'Gửi mã đăng nhập'}</button></form>${challenge?'<button class="secondary" id="restart-login">Đổi email</button>':''}<a href="/">Về ứng dụng</a></section>`;document.querySelector('#restart-login')?.addEventListener('click',()=>{challenge=null;login();});document.querySelector('#management-login').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const button=event.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(event.target));if(challenge){await call('auth/verify-code',{id:challenge.id,code:data.code});challenge=null;await boot();}else{if(Date.now()<resendAt)throw Error('Vui lòng đợi 60 giây trước khi yêu cầu mã mới.');loginEmail=data.email.trim();challenge=await call('auth/request-code',{purpose:'login',email:loginEmail});resendAt=Date.now()+60000;login();}}catch(error){const el=document.querySelector('#login-error');if(el)el.textContent=error.message;else notice(error.message);}finally{busy=false;if(button.isConnected)button.disabled=false;}};}
async function load(){const result=await call(admin?'admin/cards?status='+status:'cards/mine');cards=result.cards;selected=null;render();}
function render(){section='cards';const shown=admin?cards:cards.filter(c=>c.status===status);root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">${admin?'ADMIN WORKSPACE':'YOUR DEBT CARDS'}</span><h1>${admin?'Duyệt thẻ báo nợ':'Thẻ đã gửi'}</h1><p>${admin?'Đọc câu chuyện, kiểm tra thông tin và quyết định trước khi công khai.':'Theo dõi kết quả xét duyệt. Thẻ chờ duyệt hoặc bị từ chối sẽ không xuất hiện ở trang quẹt.'}</p></div><div class="management-account"><span>${e(user.email||user.name)}</span>${admin?'<button id="fraud-monitoring" class="secondary">Fraud Monitoring</button>':''}${admin&&user.isOwner?'<button id="manage-admins" class="secondary">Quản lý admin</button>':''}<button id="refresh" class="secondary">↻ Tải lại</button>${admin?'<button id="logout" class="secondary">Đăng xuất</button>':''}</div></section><nav class="status-tabs" aria-label="Trạng thái thẻ">${Object.entries(labels).map(([key,label])=>`<button data-status="${key}" aria-pressed="${key===status}">${label}${!admin?` <span>${cards.filter(c=>c.status===key).length}</span>`:''}</button>`).join('')}</nav><div class="management-grid"><section class="submission-list" aria-label="Danh sách thẻ">${shown.length?shown.map(c=>`<button class="submission-summary" data-card="${e(c.id)}"><span class="status-badge ${c.status}">${labels[c.status]}</span><h2>${e(c.debts[0].title)}</h2><strong>${money(c.debts.reduce((sum,d)=>sum+d.amount,0))}</strong><p>${c.debts.length} khoản nợ · ${e(new Date(c.createdAt).toLocaleString('vi-VN'))}</p>${admin?`<small>${e(c.identity.name)} · ${e(c.identity.email)}</small>`:''}${c.reason?`<p class="rejection-reason">Lý do: ${e(c.reason)}</p>`:''}<span class="open-card">Xem thẻ →</span></button>`).join(''):'<div class="management-empty"><span>♧</span><h2>Chưa có thẻ trong mục này</h2><p>Thẻ mới gửi sẽ xuất hiện trong mục Chờ duyệt.</p></div>'}</section><section id="review-panel" class="review-panel"><div class="review-placeholder"><span>▤</span><h2>Chọn một thẻ để xem</h2><p>${admin?'Nội dung đầy đủ chỉ hiển thị cho chủ thẻ và admin.':'Xem lại nội dung và trạng thái xét duyệt của bạn.'}</p></div></section></div><p id="management-notice" role="alert"></p>`;
 root.querySelectorAll('[data-status]').forEach(button=>button.onclick=async()=>{if(busy)return;status=button.dataset.status;try{if(admin)await load();else render();}catch(error){notice(error.message);}});
 root.querySelectorAll('[data-card]').forEach(button=>button.onclick=()=>{if(!busy)show(cards.find(c=>c.id===button.dataset.card));});
 document.querySelector('#fraud-monitoring')?.addEventListener('click',()=>{if(!busy)fraudMonitoring.show();});
 document.querySelector('#manage-admins')?.addEventListener('click',async()=>{if(busy)return;try{await loadMembers();}catch(error){notice(error.message);}});
 document.querySelector('#refresh').onclick=async()=>{if(busy)return;try{await load();}catch(error){notice(error.message);}};
 document.querySelector('#logout')?.addEventListener('click',async()=>{try{await call('auth/logout',{});user=null;login();}catch(error){notice(error.message);}});
}
function show(card){selected=card;root.querySelectorAll('[data-card]').forEach(b=>b.classList.toggle('selected',b.dataset.card===card.id));const projected=publicCard(card.debts,card.privacy,card.identity);document.querySelector('#review-panel').innerHTML=`<div class="review-heading"><span class="status-badge ${card.status}">${labels[card.status]}</span><small>#${e(card.id.slice(0,8))}</small></div><h2>${e(card.identity.name)}</h2><p class="private-label">Thông tin riêng tư · ${e(card.identity.email)}</p><div class="review-debts">${card.debts.map((d,i)=>`<article><span class="eyebrow">KHOẢN NỢ ${i+1}</span><h3>${e(d.title)}</h3><strong>${money(d.amount)}</strong><p class="story">${e(d.story)}</p></article>`).join('')}</div><section class="public-preview"><span class="eyebrow">BẢN HIỂN THỊ CÔNG KHAI</span><h3>${e(projected.name)}${projected.age?`, ${e(projected.age)}`:''}</h3>${projected.location?`<p>${e(projected.location)}</p>`:''}${projected.photo?`<img class="review-photo" src="${e(projected.photo)}" alt="Ảnh đại diện công khai">`:''}${projected.debts.map(d=>`<h4>${e(d.title)}</h4><strong>${money(d.amount)}</strong>${d.story?`<p class="story">${e(d.story)}</p>`:''}`).join('')}<p class="privacy-note">${Object.entries({realName:'Tên thật',age:'Tuổi',location:'Địa điểm',photo:'Ảnh',publicStory:'Câu chuyện'}).map(([key,label])=>`${label}: ${card.privacy[key]?'On':'Off'}`).join(' · ')}</p></section>${card.reason?`<p class="rejection-reason">Lý do từ chối: ${e(card.reason)}</p>`:''}${admin&&card.status==='pending'?'<form id="review-form"><label for="review-reason">Ghi chú / lý do từ chối</label><textarea id="review-reason" name="reason" maxlength="1000" placeholder="Bắt buộc khi từ chối. Chủ thẻ sẽ nhìn thấy lý do này."></textarea><label class="approve-confirm"><input id="review-confirm" type="checkbox">Tôi đã kiểm tra nội dung và bản hiển thị công khai.</label><div class="review-actions"><button class="secondary reject" type="submit" name="decision" value="rejected">Từ chối</button><button type="submit" name="decision" value="approved">✓ Duyệt & công khai</button></div><p id="review-error" role="alert"></p></form>':''}`;
 document.querySelector('#review-form')?.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const decision=event.submitter?.value,reason=document.querySelector('#review-reason').value.trim(),error=document.querySelector('#review-error');if(decision==='approved'&&!document.querySelector('#review-confirm').checked){error.textContent='Hãy xác nhận đã kiểm tra thẻ trước khi duyệt.';return;}if(decision==='rejected'&&!reason){error.textContent='Vui lòng nhập lý do từ chối.';return;}busy=true;event.target.querySelectorAll('button').forEach(b=>b.disabled=true);try{await call('admin/cards/'+encodeURIComponent(selected.id)+'/review',{decision,reason});await load();notice(decision==='approved'?'Đã duyệt. Thẻ có thể xuất hiện trong trang quẹt.':'Đã từ chối. Chủ thẻ có thể xem lý do.');}catch(err){if(error.isConnected)error.textContent=err.message;else notice(err.message);event.target.querySelectorAll('button').forEach(b=>b.disabled=false);}finally{busy=false;}});
}
boot();

async function loadMembers(){const result=await call('admin/members');members=result.members;section='members';renderMembers();}
function renderMembers(){
 root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">OWNER WORKSPACE</span><h1>Quản lý admin</h1><p>Cấp quyền duyệt thẻ cho người cùng quản lý DebtFreeLately.</p></div><button id="back-to-cards" class="secondary">← Duyệt thẻ</button></section><div class="members-layout"><section class="member-add-panel"><h2>Thêm thành viên admin</h2><p>Admin được thêm có thể đọc nội dung riêng tư của thẻ đã gửi và duyệt hoặc từ chối thẻ. Chỉ chủ sở hữu được cấp hoặc thu hồi quyền admin.</p><form id="member-add"><label for="member-email">Email thành viên</label><input id="member-email" name="email" type="email" autocomplete="off" maxlength="254" placeholder="thanhvien@example.com" required><p class="member-help">Thành viên cần đăng ký tài khoản bằng đúng email này, xác minh email rồi đăng nhập trang admin. Không gửi email mời tự động.</p><button>Cấp quyền admin</button></form></section><section class="member-list-panel"><h2>Thành viên quản trị <span>${members.length}</span></h2><ul class="member-list">${members.map(member=>`<li><div><strong>${e(member.email)}</strong><span class="member-role">${member.role==='owner'?'Chủ sở hữu':'Admin · Duyệt thẻ'}</span></div>${member.role==='owner'?'<span class="owner-protected">Được bảo vệ</span>':`<button class="secondary" data-revoke="${e(member.email)}">Thu hồi quyền</button>`}</li>`).join('')}</ul></section></div><p id="management-notice" role="alert"></p>`;
 document.querySelector('#back-to-cards').onclick=async()=>{if(busy)return;try{await load();}catch(error){notice(error.message);}};
 document.querySelector('#member-add').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const email=document.querySelector('#member-email').value.trim();event.target.querySelector('button').disabled=true;try{members=(await call('admin/members',{email})).members;renderMembers();notice('Đã cấp quyền admin cho '+email+'.');}catch(error){notice(error.message);event.target.querySelector('button').disabled=false;}finally{busy=false;}};
 root.querySelectorAll('[data-revoke]').forEach(button=>button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;const email=button.dataset.revoke;try{members=(await call('admin/members/revoke',{email})).members;renderMembers();notice('Đã thu hồi quyền admin của '+email+'.');}catch(error){notice(error.message);button.disabled=false;}finally{busy=false;}});
}
